package com.trombokendu.chronos.ui;import javax.swing.*;import java.awt.*;import java.time.*;import java.util.*;import com.trombokendu.chronos.domain.*;import com.trombokendu.chronos.ledger.*;import com.trombokendu.chronos.concurrency.*;public final class ChronosFrame extends JFrame{private static final long serialVersionUID=1L;private final transient EventStore store;private final transient LedgerWriter writer;private final transient LedgerTableModel model=new LedgerTableModel();private final transient JLabel balance=new JLabel();public ChronosFrame(EventStore s,LedgerWriter w){super("Chronos Ledger");store=s;writer=w;setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);setSize(1100,720);setLocationRelativeTo(null);setLayout(new BorderLayout(10,10));JPanel top=new JPanel(new GridLayout(1,2));top.add(new JLabel("CHRONOS LEDGER  |  Event-sourced personal finance"));top.add(balance);add(top,BorderLayout.NORTH);JTable table=new JTable(model);table.setRowHeight(25);add(new JScrollPane(table),BorderLayout.CENTER);JPanel form=new JPanel(new FlowLayout(FlowLayout.LEFT));JComboBox<String> kind=new JComboBox<>(new String[]{"Expense","Income"});JComboBox<Category> cat=new JComboBox<>(Category.values());JTextField amount=new JTextField(8),date=new JTextField(LocalDate.now().toString(),10),note=new JTextField(14);JButton add=new JButton("Post transaction");add.addActionListener(e->{try{Kind k=kind.getSelectedIndex()==0?Kind.EXPENSE:Kind.INCOME;TransactionPosted ev=new TransactionPosted(UUID.randomUUID(),Instant.now(),LocalDate.parse(date.getText()),k,(Category)cat.getSelectedItem(),Money.of(amount.getText()),note.getText(),Optional.empty(),Optional.empty());add.setEnabled(false);writer.submit(ev).whenComplete((v,x)->SwingUtilities.invokeLater(()->{add.setEnabled(true);if(x!=null)JOptionPane.showMessageDialog(this,x.getMessage());refresh();}));}catch(RuntimeException x){JOptionPane.showMessageDialog(this,x.getMessage());}});form.add(kind);form.add(cat);form.add(amount);form.add(date);form.add(note);form.add(add);JButton voidBtn=new JButton("Void selected");voidBtn.addActionListener(e->{int r=table.getSelectedRow();if(r>=0){StoredEvent se=store.all().get(table.convertRowIndexToModel(r));if(se.event() instanceof TransactionPosted t)writer.submit(new TransactionVoided(UUID.randomUUID(),Instant.now(),t.eventId(),"User correction")).thenRun(()->SwingUtilities.invokeLater(this::refresh));}});form.add(voidBtn);JButton verify=new JButton("Verify integrity");verify.addActionListener(e->{var report=HashChain.verify(store.all());JOptionPane.showMessageDialog(this,report.message()+(report.brokenSeq().isPresent()?" at seq "+report.brokenSeq().getAsLong():""));});form.add(verify);add(form,BorderLayout.SOUTH);refresh();}private void refresh(){model.setRows(store.all());balance.setText("Balance: ₹"+store.replay(new BalanceProjection()).balance());}}
